SELECT sum(total_cost_usd) as total_cost_local_model
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND arm = 'primary';

select avg(is_correct::int) as accuracy 
from marts.fct_outcomes 
where setup = 'B_local' and arm = 'primary' and split = 'test';

SELECT AVG(is_correct::int) AS accuracy
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';

select sum(case when is_correct = false then 1.0 else 0 end) / count(*) as invalid_output_rate
from marts.fct_outcomes
where setup = 'B_local' and split = 'test' and arm = 'primary';

SELECT AVG(input_tokens + output_tokens) AS avg_total_tokens
FROM marts.fct_requests
WHERE setup = 'vllm' AND split = 'test';

select count(*) as n_decisions
from marts.fct_outcomes
where setup = 'B_local' and split = 'test' and arm = 'primary';

SELECT COUNT(*) AS tenant_count
FROM marts.dim_tenant
WHERE tenant_id NOT LIKE 'test-%';

SELECT monthly_budget_usd 
FROM marts.dim_tenant 
WHERE tenant_id = 'billing';

SELECT count(*) 
FROM support.tickets 
WHERE tenant_id = 'support' AND priority = 'high';

SELECT resolution_hours 
FROM support.sla_policies 
WHERE tenant_id = 'sales' AND priority = 'high';

SELECT AVG(latency_ms) AS avg_latency_ms
FROM marts.fct_requests
WHERE provider = 'vllm' AND split = 'test' AND arm = 'primary';

select count(distinct gold_label) as n_distinct_gold_intents
from marts.fct_outcomes
where split = 'test' and arm = 'primary';

select count(*) 
from support.tickets 
where tenant_id = 'billing' and channel = 'chat';

select sum(output_tokens) as total_output_tokens
from marts.fct_requests
where setup = 'B_local' and split = 'test' and arm = 'primary';

SELECT MIN(opened_at) AS earliest_opened_at
FROM support.tickets
WHERE tenant_id = 'sales';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

select count(*) as n_invalid_decisions
from marts.fct_outcomes
where setup = 'B_local' and split = 'test' and arm = 'primary' and not is_correct;

SELECT COUNT(*) AS current_headcount
FROM support.agents
WHERE is_active AND team NOT LIKE 'test-%';

SELECT AVG(is_correct::int) AS accuracy
FROM marts.fct_outcomes
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';

select sum(total_cost_usd) / nullif(count(*) filter (where is_correct), 0) as cost_per_correct_usd 
from marts.fct_outcomes 
where setup = 'B_local' and arm = 'primary';

select sum(total_cost_usd) as total_spent
from marts.fct_outcomes
where setup = 'B_local' and split = 'test' and arm = 'primary';

select sum(total_cost_usd) / nullif(count(*) filter (where n_correct > 0), 0) as cost_per_correct_usd 
from marts.mart_cost_per_outcome 
where setup = 'B_local' and split = 'test' and arm = 'primary';

select count(distinct ticket_id) filter (where event_type = 'reopened') as reopened_tickets
from support.ticket_events
where actor_type = 'agent';

SELECT sum(billed_usd) as total_billed_usd
FROM marts.fct_requests
WHERE setup = 'B_local' AND split = 'test' AND arm = 'primary';
